import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"28、【大过】 巽下兑上","description":"周易尚氏学 - 28、【大过】 巽下兑上","frontmatter":{"title":"28、【大过】 巽下兑上","description":"周易尚氏学 - 28、【大过】 巽下兑上"},"headers":[],"relativePath":"zh/classics/shangshi/033.md","filePath":"zh/classics/shangshi/033.md"}'),s={name:"zh/classics/shangshi/033.md"};function h(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_28、【大过】-巽下兑上" tabindex="-1">28、【大过】 巽下兑上 <a class="header-anchor" href="#_28、【大过】-巽下兑上" aria-label="Permalink to “28、【大过】 巽下兑上”">​</a></h1><p>过失也。谓中四阳隐于阴中。失其用也。说文栋极也。尔雅栋谓之俘（左木）。郭璞云。屋脊也。易林以坎为栋为屋极。大过本大坎也。坎以中爻为栋。大过以三四为栋。桡。释文云。由折也。兑毁折。巽陨落。故栋桡。以易理言。朋承阳则利。利有攸往。应指初。升初六曰允升。曰上合志。大过初与升初同。而四有应。故往利也。虞翻知阳爻无利往者。乃谓二变应五故利往。如虞说。传云栋桡本末弱。本谓初。初亦失位可变也。尚何弱这有哉。乃自宋朱震以来。即承其说。甚矣其不思也。</p><p>彖曰。大过。大者过也。栋挠？？。本末弱也。刚过而中。巽而说行。利有攸往。乃亨。大过之时大矣哉。</p><p>卦气图。大过十月卦。闭塞成冬。故曰大过时。</p><p>大过过字。彖传未明释。后儒或以过往为说。先天位兑左巽右中过乾或以过盛为说。此说尤不协。四阳五阳卦多矣。胡此独盛皆有可疑。愚按太玄拟大过为失。言四阳为阴所锢。失其用也。故汉人皆谓大过为死卦。易林明夷之大过云。言笑未毕。忧来暴卒。又大壮之大过云。道绝不通。商旅失意。又既济之大过云。身加槛缆。囚系缚束。太玄又拟为剧。剧甚也。病也。皆谓阴大贼阳。阳失其用。与易林说合若符契。</p><p>象曰。泽灭木。大过。君子以独立不惧。通世无闷。</p><p>不曰泽中有木。而曰泽灭木。此汉人死卦之说所由来也。灭者人之所惧。君子则独立不惧。巽为寡故曰独。乾为惕故曰惧。兑悦故不惧。阳陷阴中。阴伏不出。故曰遁世。过世宜有忧矣。乃君子则适世无闷。以兑悦在终也。大象每反以见义。此亦其一也。</p><p>初六。籍用白茅。无咎。</p><p>藉荐也。凡以物承物曰藉。曲礼执玉。其有藉者则裼。无籍者则袭。注籍藻也。疏执玉必有藻以承玉。巽为伏。初在下。故曰籍。巽为白为茅。茅柔物。初阴故曰藉用白茅。又祭时籍茅于地。用以缩酒。而巽为漏。井九三雍（下兀）敝漏于象尤切。</p><h3 id="象曰。藉用白茅。桑在下也。" tabindex="-1">象曰。藉用白茅。桑在下也。 <a class="header-anchor" href="#象曰。藉用白茅。桑在下也。" aria-label="Permalink to “象曰。藉用白茅。桑在下也。”">​</a></h3><p>初柔在下。承阳故无咎</p><p>九二。枯杨生梯。老夫得其女妻。无不利。</p><p>巽。为杨。为陨落。为枯。易林泰之威云。老杨日衰。条多枯枝。噬嗑之否云。朽根枯树。是以咸否互巽为枯也。梯郑作美。木更生。按诗卫风手如柔荑。传云。如荑之新生。然则荑为木新生之条。盖弟（左禾）荑同字。庄子知北游云。在荑稗。释文云美本又作弟（左禾）。是其证。乾为生。巽为木。巽柔。故曰枯杨生弟（左禾）。伏震为老夫。巽为女妻。女妻者。少妻。二下孚于阴。故无不利。巽为利也。易林遇震即曰老夫。遇巽即曰少齐。曰少姬。本此也。详焦氏易诂。虞翻以乾老为枯。岂知乾实虽老不枯。又以乾老为老夫。兑为少女。创二应上初应五之例。以圆其说。是贞悔不必拘。而应与常例可破也。乃清儒翕然从之。异已。只俞樾以虞说为不通。知用旁通。打破二千年之谬误。为功甚伟。特又以大过二五与颐二五相升降以取象。岂知巽即为少妻。兑即为老妇。易林有明征。不必如是穿凿也。故夫象一失传。虽以俞氏之深识旁通。且洞明阳顺阴逆之理。亦无如何也。</p><h3 id="象曰。老夫女妻。过以相与也。" tabindex="-1">象曰。老夫女妻。过以相与也。 <a class="header-anchor" href="#象曰。老夫女妻。过以相与也。" aria-label="Permalink to “象曰。老夫女妻。过以相与也。”">​</a></h3><p>过以相与。言其不当。非谓初可过四应五。二可过五应上也。</p><p>九三。栋桡。凶。</p><p>初爻本弱。故楝桡。上虽有应。然四五皆阳。得敌。九三不能应上。故曰不可以有辅。</p><h3 id="象曰。栋桡之凶。不可以有辅也。" tabindex="-1">象曰。栋桡之凶。不可以有辅也。 <a class="header-anchor" href="#象曰。栋桡之凶。不可以有辅也。" aria-label="Permalink to “象曰。栋桡之凶。不可以有辅也。”">​</a></h3><p>辅。佐助也。</p><p>九四。栋隆。吉。有它吝</p><p>巽为高。四居巽上。故曰栋隆吉。有它吝者。言四应在初。四若它往应之。则为二三所忌。而致吝矣。四与三不同。三与初同体。本弱无如何。若四只不与初应。则吉也。</p><h3 id="象曰。栋隆之吉。不桡乎下也。" tabindex="-1">象曰。栋隆之吉。不桡乎下也。 <a class="header-anchor" href="#象曰。栋隆之吉。不桡乎下也。" aria-label="Permalink to “象曰。栋隆之吉。不桡乎下也。”">​</a></h3><p>不桡乎下。即不应初。</p><p>九五。枯杨生华。老妇得其士夫。无咎无誉。</p><p>兑为反巽。故仍曰枯杨。兑为华。易林否之成云。华落实槁。以咸上兑为华。需之剥云。老妇亡夫。以剥伏兑为老妇。又否之中。孚老妾据机。以中孚下兑为老妾。伏艮为士夫。故曰老妇得其士夫。五比阴志行故无咎。下无应。故无誉。虞翻以五应初巽为老妇。易无此例也。盖易有伏象。伏即旁通。即对象。人知之。而旁通之原理。鲜能明之。文言云。旁通情也。情者感也。言阴阳不能相离也。故夫茅茹坤象也。泰初爻亦言之。云雨坤坎象也。小畜亦言之。否初言茅茹。小过言云雨。则用正象。易林本之。正伏象常不分。略如见一男子。可推知其家必有妇。见一妇人。可推知其家必有夫也。然非以夫为妇。以妇为夫。使男女无别也。易系辞取象可用伏。而义则正也。彼夫王引之讥虞翻用旁通。致阴阳无别。是皆于旁通情。情字失诂。故于易理隔阂如斯也。大过老夫士夫。皆在对象。而自荀虞以来。皆苦于本象求之。胡有得乎。</p><h3 id="象曰。枯杨生华。何可久也。老妇士夫。亦可且也。" tabindex="-1">象曰。枯杨生华。何可久也。老妇士夫。亦可且也。 <a class="header-anchor" href="#象曰。枯杨生华。何可久也。老妇士夫。亦可且也。" aria-label="Permalink to “象曰。枯杨生华。何可久也。老妇士夫。亦可且也。”">​</a></h3><p>匹配失宜。故可丑。</p><p>上六。过涉灭顶。凶。无咎。</p><p>乾为首。故为顶。泽水在上。故灭顶。与比之无首义同也。灭顶则死故凶。大过之为死卦在此。然上六当位有应。凶则有之。咎则无也。故象曰不可咎。</p><h3 id="象曰。过涉之凶。不可咎也。" tabindex="-1">象曰。过涉之凶。不可咎也。 <a class="header-anchor" href="#象曰。过涉之凶。不可咎也。" aria-label="Permalink to “象曰。过涉之凶。不可咎也。”">​</a></h3><p>不可咎。言致命遂义。杀身成仁。属于天者虽凶。而咎则未有也。</p><p>附</p><p>颐大过四象在先天处四隅。而包灭地水火于其中。天地水火四正卦。上经首尾也。亦即离坎也。而即列于离坎之前。以结上经。最耐寻味。</p>',33)])])}const f=e(s,[["render",h]]);export{_ as __pageData,f as default};
